50	export async function runPipeline(
51	  db: Database,
52	  runId: string,
53	  stages: Stage[],
54	  o: { dataDir: string; sleep?: (ms: number) => Promise<void> },
55	): Promise<RunStatus> {
56	  const initial = getRun(db, runId);
57	  if (initial.status !== 'running') return initial.status;
58	
59	  const sleep = o.sleep ?? defaultSleep;
60	  const runDir = join(o.dataDir, 'runs', runId);
61	  let feedback: string | null = readRecutFeedback(db, runId);
62	
63	  let i = stages.findIndex((s) => !isStageDone(db, runId, s.name));
64	  if (i === -1) i = stages.length;
65	
66	  while (i < stages.length) {
67	    const stage = stages[i]!;
68	    const ctx: StageContext = {
69	      run: getRun(db, runId),
70	      dataDir: o.dataDir,
71	      runDir,
72	      read: <T>(name: StageName) => readArtifact<T>(o.dataDir, runId, name),
73	      log: (message: string) => appendEvent(db, runId, stage.name, message),
74	      feedback,
75	    };
76	
77	    const attempt = beginStageAttempt(db, runId, stage.name);
78	    try {
79	      const result = await stage.run(ctx);
80	      writeArtifact(o.dataDir, runId, stage.name, result.artifact);
81	
82	      if (result.final) {
83	        db.transaction(() => {
84	          markStageDone(db, runId, stage.name);
85	          setRunFinal(db, runId, result.final!.status, result.final!.reason);
86	        })();
87	        return result.final.status;
88	      }
89	
90	      if (result.loopBackTo) {
91	        const target = stages.findIndex((s) => s.name === result.loopBackTo);
92	        if (target === -1) throw new Error(`loopBackTo names an unknown stage: ${result.loopBackTo}`);
93	        if (getRun(db, runId).loops < 2) {
94	          db.transaction(() => {
95	            markStageDone(db, runId, stage.name);
96	            incrementLoops(db, runId);
97	            for (let j = target; j < stages.length; j++) resetStage(db, runId, stages[j]!.name);
98	          })();
99	          feedback = result.reason ?? null;
100	          i = target;
101	          continue;
102	        }
103	        db.transaction(() => {
104	          markStageDone(db, runId, stage.name);
105	          setRunFinal(db, runId, 'blocked', result.reason ?? null);
106	        })();
107	        return 'blocked';
108	      }
109	
110	      markStageDone(db, runId, stage.name);
111	      i += 1;
112	    } catch (err) {
113	      if (err instanceof BudgetExceededError) {
114	        setRunFinal(db, runId, 'blocked', 'budget');
115	        return 'blocked';
116	      }
117	      const message = err instanceof Error ? err.message : String(err);
118	      if (attempt >= stage.maxAttempts) {
119	        db.transaction(() => {
120	          markStageFailed(db, runId, stage.name, message);
121	          setRunFinal(db, runId, 'failed', message);
122	        })();
123	        return 'failed';
124	      }
125	      markStageFailed(db, runId, stage.name, message);
126	      await sleep(500 * 2 ** attempt);
127	    }
128	  }
129	
130	  setRunFinal(db, runId, 'needs_approval', null);
131	  return 'needs_approval';
132	}
